def solve(s):
    if s is None:
        return True
    s = str(s)
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opens = set('([{')
    for ch in s:
        if ch in opens:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return len(stack) == 0

